css:
.flow { display:flex; flex-wrap:wrap; align-items:center; gap:7px 9px;
      margin:9px 0; padding:12px 14px; border:1.5px solid #cfe3d6;
      border-radius:14px; background:#f7fbf8; }

.flow>.st { display:inline-block; padding:5px 11px; border:1.5px solid #b9d9c6;
      border-radius:9px; background:#fff; font-size:16px; line-height:1.45;
      font-style:normal; font-weight:600; color:#1d3a2a; }

.fstep>.no { position:relative; z-index:2; flex:none; width:34px; height:34px;
      border-radius:50%; background:#1b6b3a; border:3px solid #d7efe0;
      color:#fff; font-size:13.5px; font-weight:700; font-style:normal;
      display:flex; align-items:center; justify-content:center;
      font-variant-numeric:tabular-nums; }

.fstep>.st { flex:1; min-width:0; margin-left:20px; background:#fff;
      border:1.5px solid #d8e8de; border-radius:11px; padding:9px 13px;
      font-size:16.5px; }

.fstep>.st::before { content:""; display:inline-block; width:5px; height:5px;
      border-radius:50%; background:#1b6b3a; vertical-align:middle;
      margin-right:9px; }
